BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-20532'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='3A1464' OR source_url ~ '[?&]id=20532(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='f1451464-505a-418b-b2ef-691548920532' OR slug='sam-thanarat-pak-chong-resort-79-rooms-3a1464' OR (abs(latitude-14.611394)<0.0001 AND abs(longitude-101.405673)<0.0001 AND abs(land_area_sqm-16484)<1)) THEN RAISE NOTICE 'SAM 3A1464 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, custom_unit_number, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('f1451464-505a-418b-b2ef-691548920532', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'hotel_resort', 'business', 'sale', 'whole_property', 'ทรัพย์ที่พักถนนธนะรัชต์ ปากช่อง 79 ห้องตามสำรวจ 10 ไร่ 1 งาน 21 ตร.ว.', 'รายละเอียดทรัพย์

ทรัพย์โรงแรม/รีสอร์ท เลขที่ 135/1 หมู่ 6 ถนนธนะรัชต์ (ทล.2090) ตำบลหนองน้ำแดง อำเภอปากช่อง จังหวัดนครราชสีมา โฉนดเลขที่ 62953 จำนวน 1 ฉบับ เนื้อที่ 10 ไร่ 1 งาน 21 ตร.ว. หรือ 4,121 ตร.ว. (16,484 ตร.ม.) ราคาประกาศขาย SAM 164,455,000 บาท รหัส 3A1464 เป็นการขายทั้งทรัพย์

ข้อมูลสำรวจระบุห้องพักรวม 79 ห้อง แบ่งเป็นห้องแอร์เล็ก 16 ห้อง ห้องแอร์มาตรฐาน 23 ห้อง Deluxe 26 ห้อง และ Grand Deluxe 14 ห้อง เป็นจำนวนตามสำรวจ ไม่ใช่การรับรองสภาพพร้อมให้บริการ ต้นทางไม่ยืนยันสถานะเปิดกิจการ รายได้ ผู้เช่า ใบอนุญาตโรงแรม หรือพื้นที่ใช้สอยรวมปัจจุบัน

สิ่งปลูกสร้างและที่ดิน

ทะเบียนรับโอนระบุสิ่งปลูกสร้าง 26 รายการ ประกอบด้วยบ้านพักอาศัย 1–2 ชั้นหลายหลัง รวมอาคารร้านอาหารและห้องพัก 2 ชั้น อาคารพักอาศัยรวม 3 ชั้น ห้องน้ำรวม ศาลาอเนกประสงค์ ศาลาพักผ่อน สระว่ายน้ำ ป้อมยาม และลานคอนกรีต/ถนน ไม่ควรตีความเป็นบ้านพัก 26 หลัง เนื่องจากรายการรวมสาธารณูปโภคและพื้นที่ภายนอกด้วย

แปลงรูปคล้ายสี่เหลี่ยมผืนผ้า ด้านตะวันตกติดถนนกว้างประมาณ 48 เมตร ลึกประมาณ 344 เมตร ถนนธนะรัชต์ตาม SAM เป็นทางสาธารณะ ผิวลาดยางกว้างประมาณ 16 เมตร เขตทางประมาณ 60 เมตร ควรตรวจสภาพอาคาร ระบบไฟฟ้า ประปา สระว่ายน้ำและรายการที่รวมในการโอนจริงก่อนเสนอซื้อ

ข้อควรทราบเกี่ยวกับเอกสารสิทธิ์

SAM ระบุว่าทรัพย์ตั้งอยู่ในเขตพื้นที่ ส.ป.ก. ตามพระราชกฤษฎีกาวันที่ 8 ธันวาคม 2534 และมีที่มาจาก น.ส.3 เลขที่ 5 หน้า 188 หมู่ 6 ออกวันที่ 15 มีนาคม 2509 ซึ่งก่อนการประกาศเขตดังกล่าว ปัจจุบันส่วนสรุประบุเอกสารเป็นโฉนดเลขที่ 62953 ข้อมูลลำดับวันที่นี้ไม่ใช่การยืนยันว่าทรัพย์ไม่มีข้อจำกัดหรือข้อพิพาท ผู้สนใจควรตรวจที่มาของโฉนด แนวเขต สถานะสิทธิและข้อกำหนดการใช้ประโยชน์กับหน่วยงานที่เกี่ยวข้องก่อนเสนอซื้อ

สีผังเมืองตามหัวข้อ SAM ระบุสีขาวมีกรอบและเส้นทแยงสีเขียว ควรตรวจประเภทและข้อกำหนดตามผังปัจจุบัน ไม่อนุมานสิทธิประกอบกิจการโรงแรมจากการจัดหมวดประกาศเพียงอย่างเดียว

ทำเลและการเดินทาง

ตั้งอยู่ในย่านที่อยู่อาศัย พาณิชยกรรมและแหล่งท่องเที่ยว ใกล้อุทยานแห่งชาติเขาใหญ่ ที่ว่าการอำเภอปากช่อง วัดโป่งกะสังและ อบต.หนองน้ำแดง ตามข้อมูล SAM จากถนนมิตรภาพเข้าถนนธนะรัชต์มุ่งหน้าเขาใหญ่ ผ่านไทวัสดุ แม็คโคร อบต.หนองน้ำแดง วัดบ้านนาและโรงเรียนเซนต์สตีเฟ่น อินเตอร์ฯ ถึงประมาณ กม.7 ทรัพย์อยู่ซ้ายมือ

ภาพและข้อมูลต้นทาง

ภาพจริงและผังจาก SAM รวม 20 ภาพ เป็นภาพต่างช่วงปี 2565–2566 มีภาพอาคาร พื้นที่สวน ห้องน้ำ สระว่ายน้ำ ผังสิ่งปลูกสร้างและแผนที่ ควรตรวจสภาพปัจจุบัน ภาพด้านข้างที่ติดปั๊มน้ำมันเป็นบริเวณโดยรอบ ไม่รวมปั๊มน้ำมันในรายการขาย

พิกัด 14.611394, 101.405673 ดึงจากลิงก์นำทาง SAM และตรงกับลิงก์แผนที่ เป็นจุดอ้างอิง ไม่ใช่แนวเขตรังวัด ราคาและสถานะซื้อตรงตรวจวันที่ 15 กันยายน 2569 ติดต่อ SAM 02-686-1888, sales@sam.or.th หรือ LINE @samline แจ้งรหัส 3A1464 เพื่อยืนยันเอกสารสิทธิ์ ราคา สภาพและเงื่อนไขล่าสุด', 164455000, false, 16484, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, '135/1', '135/1 หมู่ 6 ถนนธนะรัชต์', 'บริเวณ ทล.2090 กม.7', 'ถนนธนะรัชต์ (ทล.2090)', 14.611394, 101.405673, 'นครราชสีมา', 'ปากช่อง', 'หนองน้ำแดง', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-thanarat-pak-chong-resort-79-rooms-3a1464') RETURNING id INTO property_listing_id;
