INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=20532&keyref=', '3A1464', now(), 'Checked2026-09-15. THB164455000,Chanote62953,16484sqm,79surveyed rooms(16+23+26+14),26registered entries including non-guest structures. SAM land-reform area1991/predecessorNS3issued1966 disclosed without certifying rights. Operating status/licence/income unconfirmed.20authentic images2022–2023,navigation/map agree. No all-status source/page/deed/nearby duplicate matches.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'Thanarat Road Resort Property, Pak Chong — 79 Surveyed Rooms, THB164.455M', 'Hotel/resort property135/1 Moo6,Thanarat Road (Highway2090),Nong Nam Daeng,Pak Chong,Nakhon Ratchasima. One Chanote62953,total10 rai1 ngan21sq.wah,or4,121sq.wah (16,484sq.m.). SAM announced whole-property price THB164,455,000,asset3A1464.

Survey reports79 rooms:16 small air-conditioned,23 standard,26 Deluxe and14 Grand Deluxe. These are surveyed counts,not operational readiness. Current opening status,income,occupancy,hotel licence and total usable area are not confirmed by source.

Registered acquisition comprises26 entries including multiple one/two-storey residential buildings,a two-storey restaurant/rooms building,a three-storey collective residential building,shared toilets,multipurpose/rest pavilions,pool,guardhouse and concrete yard/roads. This is not26 guest houses;inventory includes facilities and external areas. Roughly rectangular plot,48m western road frontage and344m depth. SAM describes public Thanarat Road,16m paved carriageway and60m right of way. Inspect buildings,utilities,pool and transfer inventory.

Material title disclosure: SAM reports the site lies within an agricultural land-reform area under a Royal Decree dated8 December1991. Its predecessor document was NS3 number5,page188,Moo6,issued15 March1966,before that designation. Current summary lists Chanote62953. This chronology does not confirm absence of restrictions/disputes. Verify title provenance,boundaries,rights and permitted use with relevant authorities before purchase. Source zoning colour is white with green border/diagonal lines;confirm current classification and rules. Hotel marketing category does not itself establish operating permission.

Residential/commercial/tourism surroundings near Khao Yai National Park,Pak Chong district office,Wat Pong Kasang and Nong Nam Daeng local administration. From Mittraphap Road toward Khao Yai along Thanarat,pass Thai Watsadu,Makro,local administration,Wat Ban Na and St.Stephen''s International School to aroundkm7,property left.

